sqlGroup.select:
select a.* from sys_role a
where a.flag = #{flag}

	and a.rolename like '%${roleName}%'


	and a.status = #{status}



		and a.orgId = #{orgId}


		and a.orgId is null


order by a.create_time desc

select * from sys_role c where
c.orgId = #{orgId}
and c.status = #{status}
and c.flag = #{flag}
group by c.id

select * from sys_role where rolename = #{rolename}
and id != #{roleId}
and flag = #{flag}

	and orgId = #{orgId}
